    SetIndexBuffer(2, TPBuffer);
    SetIndexBuffer(3, SLBuffer);

    PlotIndexSetInteger(0, PLOT_ARROW, 233);  // Seta ↑
    PlotIndexSetInteger(1, PLOT_ARROW, 234);  // Seta ↓

