int OnCalculate(
    const int rates_total,
    const int prev_calculated,
    const datetime &time[],
    const double &open[],
    const double &high[],
    const double &low[],
    const double &close[],
    const long &tick_volume[],
    const long &volume[],
    const int &spread[])
{
    int start = MathMax(prev_calculated - 1, BarsN);

    // Guarda os últimos valores de TP/SL para cada barra
    double lastTP = 0, lastSL = 0;

    for (int i = start; i < rates_total; i++)
