            SellEntryBuffer[i] = low[i];
            lastTP = low[i] - Tppoints * _Point;
            lastSL = low[i] + Slpoints * _Point;
        }
        else
        {
            // Sem sinal novo: mantém os últimos níveis
            // (opcional: poderia zerar os buffers)
        }

        // Se não houve sinal, zera os buffers para não poluir o gráfico
        if ((high[i] <= h) && (low[i] >= l))
        {
            BuyEntryBuffer[i] = 0;
            SellEntryBuffer[i] = 0;
            // Mantém TP/SL apenas se houver sinal ativo
            if (BuyEntryBuffer[i] != 0 || SellEntryBuffer[i] != 0)
            {
                TPBuffer[i] = lastTP;
                SLBuffer[i] = lastSL;
            }
            else
            {
                TPBuffer[i] = 0;
                SLBuffer[i] = 0;
            }
        }
    }

